with with_windows as (select *, lag(salary) over (partition by job_title, level order by hire_date, id) as prev_salary, row_number() over (partition by job_title, level order by hire_date, id) as seq_no from employees) select s.id, s.full_name, s.dept_id, s.manager_id, s.salary, s.hire_date, s.is_remote, s.level, s.prev_salary, (select avg(t2.salary) from employees t2 where t2.dept_id = s.dept_id) as avg_employee_salary from with_windows s order by prev_salary nulls last
